/*selectWikTaskwkProgrmPtcptn 프로그램 참여현황 조회 Lee.Seoung.Jae*/
SELECT A.PTCPTN_YMD , TO_CHAR(TO_DATE(A.PTCPTN_YMD),'DY','NLS_DATE_LANGUAGE=korean') AS PTCPTN_DAOFTH , B.PROGRM_NM , C.* FROM ( (SELECT TO_DATE(
(SELECT PRD_BGNG_YMD FROM AFA210 WHERE 1=1 AND RESRCE_NO = #{RESRCE_NO} AND RPT_SE_CD = #{RPT_SE_CD} AND TASKWK_RPT_SN = #{TASKWK_RPT_SN})
#{PRD_BGNG_YMD}
,'YYYYMMDD') + LEVEL - 1 AS PTCPTN_YMD FROM DUAL
CONNECT BY LEVEL <= (TO_DATE(
(SELECT PRD_END_YMD FROM AFA210 WHERE 1=1 AND RESRCE_NO = #{RESRCE_NO} AND RPT_SE_CD = #{RPT_SE_CD} AND TASKWK_RPT_SN = #{TASKWK_RPT_SN})
#{PRD_END_YMD}
,'YYYYMMDD') - TO_DATE(
(SELECT PRD_BGNG_YMD FROM AFA210 WHERE 1=1 AND RESRCE_NO = #{RESRCE_NO} AND RPT_SE_CD = #{RPT_SE_CD} AND TASKWK_RPT_SN = #{TASKWK_RPT_SN})
#{PRD_BGNG_YMD}
,'YYYYMMDD')+1)) /*그리드에 표시될 날짜를 넣은 임시 테이블*/ ) A
LEFT JOIN ( SELECT DISTINCT LCTRE_YMD , LISTAGG(PROGRM_TTL_NM,', ') WITHIN GROUP(ORDER BY PROGRM_TTL_NM) OVER(PARTITION BY LCTRE_YMD) AS PROGRM_NM FROM ( SELECT DISTINCT D.LCTRE_YMD , B.PROGRM_TTL_NM FROM SDA100 A JOIN SDA300 B ON A.RESRCE_NO = B.RESRCE_NO JOIN SDA340 C ON C.RESRCE_NO = B.RESRCE_NO AND C.PROGRM_NO = B.PROGRM_NO AND C.DEL_YN = 'N' JOIN SDA320 D ON D.PROGRM_NO = C.PROGRM_NO AND D.RESRCE_NO = C.RESRCE_NO AND D.LCTRE_SN = C.LCTRE_SN WHERE A.RESRCE_NO = #{RESRCE_NO} AND A.USE_YN = 'Y' AND A.SRVC_RESRCE_LCLAS_SE_CD != '01' AND A.RSFR_INST_NO = #{INST_NO} AND A.APRV_STTS_SE_CD = '2' AND D.LCTRE_YMD BETWEEN #{PRD_BGNG_YMD} AND #{PRD_END_YMD} ) ) B ON A.PTCPTN_YMD = B.LCTRE_YMD LEFT JOIN ( SELECT TO_CHAR(C.YMD,'YYYYMMDD') AS PTCPTN_YMD /*일자*/ , (SELECT COUNT(*) FROM SDA100 A INNER JOIN SEB510 B ON A.RESRCE_NO = B.RESRCE_NO WHERE A.RSFR_INST_NO = #{INST_NO} AND A.USE_YN = 'Y' AND B.DEL_YN = 'N' AND A.APRV_STTS_SE_CD = '2')AS PTCPNT_CNT, /*재적*/ (SELECT COUNT(*) FROM SEB510 WHERE RESRCE_NO = B.RESRCE_NO AND DEL_YN = 'N' ) AS PTCPTN_NOPE /*전체인원*/ , (SELECT COUNT(*) FROM ( SELECT DISTINCT SRVC_PVSN_NO , CASE_MNG_NO , CASE_MNG_ODRNO , RESRCE_NO FROM SEB530) SEB530 INNER JOIN SEB500 ON SEB530.SRVC_PVSN_NO = SEB500.SRVC_PVSN_NO AND SEB530.RESRCE_NO = SEB500.RESRCE_NO WHERE SEB500.SRVC_PVSN_BGNG_YMD=C.YMD AND SEB530.RESRCE_NO = B.RESRCE_NO AND SEB500.DEL_YN = 'N') AS BGNG /*신규*/ , (SELECT COUNT(*) FROM ( SELECT DISTINCT BBB.SRVC_PVSN_NO , BBB.CASE_MNG_NO , BBB.CASE_MNG_ODRNO , BBB.RESRCE_NO FROM SEB530 AAA INNER JOIN SEB510 BBB ON AAA.SRVC_PVSN_NO = BBB.SRVC_PVSN_NO AND AAA.CASE_MNG_NO = BBB.CASE_MNG_NO AND AAA.CASE_MNG_ODRNO = BBB.CASE_MNG_ODRNO ) AA INNER JOIN SEB100 ON AA.CASE_MNG_NO = SEB100.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = SEB100.CASE_MNG_ODRNO WHERE C.YMD = SEB100.CASE_TRMN_YMD AND AA.RESRCE_NO = B.RESRCE_NO) AS TRMN /*종결*/ , COUNT(CASE WHEN (A.ATNC_SE_CD = '01' AND A.PTCPTN_YMD = C.YMD) THEN 1 END ) AS ATEND /*출석*/ , COUNT(CASE WHEN (A.ATNC_SE_CD = '02' AND A.PTCPTN_YMD = C.YMD) THEN 1 END ) AS ABSNC /*결석*/ , COUNT(CASE WHEN (A.ATNC_SE_CD = '03' AND A.PTCPTN_YMD = C.YMD) THEN 1 END ) AS LATEN /*지각*/ , COUNT(CASE WHEN (A.ATNC_SE_CD = '04' AND A.PTCPTN_YMD = C.YMD) THEN 1 END ) AS LRLY /*조퇴*/ , COUNT(CASE WHEN (A.ATNC_SE_CD IN ('05','06','07','08','09','10') AND A.PTCPTN_YMD = C.YMD) THEN 1 END ) AS ETC /*기타*/ , (SELECT LISTAGG( (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'ATNC_CS_SE_CD' AND CMMNS_CD_VALUE = ATNC_CS_SE_CD),', ') WITHIN GROUP (ORDER BY ATNC_CS_SE_CD) FROM SEB530 WHERE B.RESRCE_NO = SEB530.RESRCE_NO AND C.YMD = SEB530.PTCPTN_YMD) AS ETC_CS /*기타사유*/
FROM SDA100 B /*자원기본 테이블*/ LEFT JOIN SEB530 A /*자원프로그램제공 테이블*/ ON A.RESRCE_NO = B.RESRCE_NO /*자원번호*/ RIGHT JOIN (SELECT TO_DATE(
(SELECT PRD_BGNG_YMD FROM AFA210 WHERE 1=1 AND RESRCE_NO = #{RESRCE_NO} AND RPT_SE_CD = #{RPT_SE_CD} AND TASKWK_RPT_SN = #{TASKWK_RPT_SN})
#{PRD_BGNG_YMD}
,'YYYYMMDD') + LEVEL - 1 AS YMD FROM DUAL
CONNECT BY LEVEL <= (TO_DATE(
(SELECT PRD_END_YMD FROM AFA210 WHERE 1=1 AND RESRCE_NO = #{RESRCE_NO} AND RPT_SE_CD = #{RPT_SE_CD} AND TASKWK_RPT_SN = #{TASKWK_RPT_SN})
#{PRD_END_YMD}
,'YYYYMMDD') - TO_DATE(
(SELECT PRD_BGNG_YMD FROM AFA210 WHERE 1=1 AND RESRCE_NO = #{RESRCE_NO} AND RPT_SE_CD = #{RPT_SE_CD} AND TASKWK_RPT_SN = #{TASKWK_RPT_SN})
#{PRD_BGNG_YMD}
,'YYYYMMDD')+1)) C /*그리드에 표시될 날짜를 넣은 임시 테이블*/ ON 1=1 WHERE 1=1 AND B.RESRCE_NO = #{RESRCE_NO}
GROUP BY C.YMD,B.RESRCE_NO,B.PTCPTN_NOPE ) C ON C.PTCPTN_YMD = A.PTCPTN_YMD ORDER BY A.PTCPTN_YMD

